func ToIcebergTableParametersDetails(params []*Parameter) (*IcebergTableParametersDetails, error) {
	byKey := parametersByKey(params)
	var d IcebergTableParametersDetails
	if err := errors.Join(
		byKey["ALLOW_ROW_TIMESTAMP"].fillTyped(strconv.ParseBool, &d.AllowRowTimestamp),
		byKey["CATALOG"].fillTyped(ParseAccountObjectIdentifier, &d.Catalog),
		byKey["CATALOG_SYNC"].fillTyped(identityParse, &d.CatalogSync),
		byKey["DATA_METRIC_SCHEDULE"].fillTyped(identityParse, &d.DataMetricSchedule),
		byKey["DATA_RETENTION_TIME_IN_DAYS"].fillTyped(strconv.Atoi, &d.DataRetentionTimeInDays),
		byKey["DEFAULT_DDL_COLLATION"].fillTyped(identityParse, &d.DefaultDdlCollation),
		byKey["ENABLE_DATA_COMPACTION"].fillTyped(strconv.ParseBool, &d.EnableDataCompaction),
		byKey["ENABLE_ICEBERG_MERGE_ON_READ"].fillTyped(strconv.ParseBool, &d.EnableIcebergMergeOnRead),
		byKey["EXTERNAL_VOLUME"].fillTyped(ParseAccountObjectIdentifier, &d.ExternalVolume),
		byKey["ICEBERG_MERGE_ON_READ_BEHAVIOR"].fillTyped(ToIcebergTableIcebergMergeOnReadBehavior, &d.IcebergMergeOnReadBehavior),
		byKey["LOG_EVENT_LEVEL"].fillTyped(ToLogLevel, &d.LogEventLevel),
		byKey["MAX_DATA_EXTENSION_TIME_IN_DAYS"].fillTyped(strconv.Atoi, &d.MaxDataExtensionTimeInDays),
		byKey["OPTIMIZE_DATA_LAYOUT"].fillTyped(strconv.ParseBool, &d.OptimizeDataLayout),
		byKey["QUOTED_IDENTIFIERS_IGNORE_CASE"].fillTyped(strconv.ParseBool, &d.QuotedIdentifiersIgnoreCase),
		byKey["REPLACE_INVALID_CHARACTERS"].fillTyped(strconv.ParseBool, &d.ReplaceInvalidCharacters),
		byKey["STORAGE_SERIALIZATION_POLICY"].fillTyped(ToStorageSerializationPolicy, &d.StorageSerializationPolicy),
		byKey["TARGET_FILE_SIZE"].fillTyped(ToIcebergTableTargetFileSize, &d.TargetFileSize),
	); err != nil {
		return nil, err
	}
	return &d, nil
}

func (v *icebergTables) ShowParametersDetails(ctx context.Context, id SchemaObjectIdentifier) (*IcebergTableParametersDetails, error) {
	params, err := v.ShowParameters(ctx, id)
	if err != nil {
		return nil, err
	}
	return ToIcebergTableParametersDetails(params)
}
